-- Mật khẩu dev chung cho mọi tài khoản: Neko@2026 (BCrypt $2a$, tương thích Spring BCryptPasswordEncoder)
WITH h AS (SELECT crypt('Neko@2026', gen_salt('bf', 10)) AS v)
UPDATE users SET password_hash = h.v FROM h;

